            { "label": "有一个关键决策需要推翻", "description": "某个重要设计选择在实现后证明是错误的方向" }
          ]
        },
        "g3": {
          "header": "集成面",
          "question": "G3. 新代码与现有系统的集成面是否干净？\n\n本轮的集成点：{integration_points}",
          "multiSelect": false,
          "dynamic": true,
          "options": [
            { "label": "干净，耦合合理 (recommended)", "description": "新代码通过清晰的接口与旧系统交互，没有不合理的依赖" },
            { "label": "基本干净，个别耦合可优化", "description": "有一两处可以解耦，但不影响整体架构" },
            { "label": "耦合偏紧，需要重构接口", "description": "新老代码之间的交互方式不够清晰，后续会成为维护负担" },
            { "label": "应该完全独立", "description": "新功能应该是独立模块，不应该与现有系统共享内部状态" }
          ]
        },
        "g4": {
          "header": "约束发现",
          "question": "G4. 实现过程中发现的约束和边界条件是否被充分记录？\n\n发现的约束：{discovered_constraints}",
          "multiSelect": false,
          "dynamic": true,
          "options": [
            { "label": "充分记录 (recommended)", "description": "所有发现的限制（如 4 option 上限）已写入文档或代码注释" },
