    "quick_mode_questions": ["a1", "b1", "c1", "d2", "e1", "e1b", "f1"]
  },
  "sections": {
    "A": {
      "title": "整体视觉",
      "title_en": "Overall Visual",
      "questions": {
        "a1": {
          "header": "配色",
          "question": "A1. 整体配色是否符合预期？",
          "multiSelect": false,
          "options": [
            { "label": "满意，不需要调整 (recommended)", "description": "颜色搭配和谐，符合技能定位和输出场景，无需改动" },
            { "label": "基本满意，色调可微调", "description": "整体方向对，但个别颜色需要调整饱和度、明度或对比度" },
            { "label": "不满意，需要重新设计", "description": "配色方案与预期差距较大，需要重新选择色板或调整主色调" }
          ]
        },
        "a2": {
          "header": "字体",
          "question": "A2. 字体搭配是否合适？",
          "multiSelect": false,
          "options": [
            { "label": "合适，保持现状 (recommended)", "description": "Cormorant Garamond 标题 + Inter 正文 + JetBrains Mono 代码，层级清晰" },
            { "label": "标题字体需要更换", "description": "Cormorant Garamond 不适合当前风格，建议换用其他标题字体" },
            { "label": "正文字体需要更换", "description": "Inter 在正文中的可读性或风格不匹配，建议换用其他正文字体" },
            { "label": "代码字体需要更换", "description": "JetBrains Mono 在代码块中的显示效果不理想，建议换用其他等宽字体" }
          ]
        },
        "a3": {
          "header": "布局",
          "question": "A3. 页面布局是否合理？",
          "multiSelect": false,
          "options": [
            { "label": "合理，保持现状 (recommended)", "description": "最大宽度 780px 居中，信息密度适中，阅读体验良好" },
            { "label": "部分布局需要调整", "description": "整体可用，但某些区域的间距、对齐或响应式行为需要微调" },
            { "label": "建议换成其他布局", "description": "当前布局不符合使用场景，建议采用完全不同的版式结构" }
          ]
        }
      }
    },
    "B": {
      "title": "导航 / TOC",
      "title_en": "Navigation / TOC",
      "questions": {
        "b1": {
          "header": "TOC分类",
          "question": "B1. TOC 条目按类型分组是否提升了可读性？",
          "multiSelect": false,
          "options": [
            { "label": "是，明显提升 (recommended)", "description": "分组后能快速定位某一类内容，浏览效率显著提高" },
            { "label": "有一点提升", "description": "分组比不分好，但提升幅度有限，分组方式还可以优化" },
            { "label": "感觉一般", "description": "分组与否差异不大，没有明显改善阅读体验" },
            { "label": "不如原来的设计", "description": "分组反而增加了认知负担，不如扁平列表直观" }
          ]
        },
        "b2": {
          "header": "图标颜色",
          "question": "B2. 各类条目的图标和颜色区分是否清晰？",
          "multiSelect": false,
          "options": [
            { "label": "清晰，一眼可辨 (recommended)", "description": "不同条目类型的视觉区分明确，无需额外思考即可识别" },
            { "label": "基本可辨，但部分颜色过于接近", "description": "大部分能区分，但个别类型的颜色在视觉上容易混淆" },
            { "label": "不够清晰，需要重新设计", "description": "当前图标和颜色的区分度不足，需要更明显的视觉差异" }
          ]
        },
        "b3": {
          "header": "跳转行为",
          "question": "B3. TOC 的点击跳转行为是否符合预期？",
          "multiSelect": false,
          "options": [
            { "label": "符合预期 (recommended)", "description": "点击后平滑滚动到目标位置，无需额外操作" },
            { "label": "跳转不准确", "description": "点击后定位偏移或跳转到错误位置，需要修复" },
            { "label": "建议增加交互反馈", "description": "跳转本身正常，但建议增加高亮当前项、滚动进度等视觉反馈" }
          ]
        }
      }
    },
    "C": {
      "title": "内容展示",
      "title_en": "Content Display",
      "questions": {
        "c1": {
          "header": "折叠设计",
          "question": "C1. 按 Turn 折叠的设计是否实用？",
